import{_ as a,o as l,c as r,a2 as i}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"修練資源開放機制","description":"","frontmatter":{},"headers":[],"relativePath":"ja/18-修炼资源开放机制.md","filePath":"ja/18-修炼资源开放机制.md"}'),d={name:"ja/18-修炼资源开放机制.md"};function e(o,t,h,n,s,u){return l(),r("div",null,[...t[0]||(t[0]=[i('<h1 id="修練資源開放機制" tabindex="-1">修練資源開放機制 <a class="header-anchor" href="#修練資源開放機制" aria-label="Permalink to &quot;修練資源開放機制&quot;">​</a></h1><table tabindex="0"><thead><tr><th>項目</th><th>内容</th></tr></thead><tbody><tr><td>文書番号</td><td>18</td></tr><tr><td>モジュール</td><td>宇宙法則と修練体系</td></tr><tr><td>キーワード</td><td>資源開放、修練資源、分配メカニズム、独占禁止、資源公平</td></tr></tbody></table><h2 id="第一節-修練資源開放機制の背景と意義" tabindex="-1">第一節 修練資源開放機制の背景と意義 <a class="header-anchor" href="#第一節-修練資源開放機制の背景と意義" aria-label="Permalink to &quot;第一節 修練資源開放機制の背景と意義&quot;">​</a></h2><p>略奪主義時代には、修練資源は最も核心的な争奪対象であった。霊脈、薬田、エネルギー鉱脈、天材地宝、修練秘境などの資源は少数の強者と宗派によって独占され、底辺の衆生はほとんど正規の修練資源を得ることができなかった。この資源独占は深刻な階層固定化を引き起こしただけでなく、資源争奪による無数の戦争と虐殺も引き起こした。資源独占は略奪主義体系の経済的基盤である——資源が少数者に独占されている限り、「誰もが道を持つ」はただの空論に過ぎない。</p><p>錨点共生文明の樹立後、「修練資源開放」は最も核心的な制度変革の一つとして採用された。修練資源開放機制の核心目標は：資源独占を打破し、すべての生命が基本的な修練資源を得られることを確保し、同時に多労多得の分配メカニズムを通じて資源の効率的な利用と持続的な創造を奨励することである。資源開放は「資源の平均分配」ではなく、「資源への公平なアクセス」である——基本的な需要を保障する前提の下、資源の分配は個人の貢献と結びつけられ、同時にいかなる形の資源独占も厳禁される。</p><p>修練資源開放機制の意義は：経済的基盤から略奪主義の土壌を根絶し、三百套修練体系の真の普及のために物質的保障を提供し、「誰もが道を持つ」という社会目標のために資源的支えを提供し、万族共進のために公平な出発点を創り出すことにある。</p><h2 id="第二節-修練資源の分類と等級付け" tabindex="-1">第二節 修練資源の分類と等級付け <a class="header-anchor" href="#第二節-修練資源の分類と等級付け" aria-label="Permalink to &quot;第二節 修練資源の分類と等級付け&quot;">​</a></h2><h3 id="_2-1-資源分類" tabindex="-1">2.1 資源分類 <a class="header-anchor" href="#_2-1-資源分類" aria-label="Permalink to &quot;2.1 資源分類&quot;">​</a></h3><p>衡元宙における修練資源は性質と用途に応じて以下の大分類に分けられる：</p><table tabindex="0"><thead><tr><th>資源カテゴリ</th><th>具体的内容</th><th>主な用途</th></tr></thead><tbody><tr><td>エネルギー系資源</td><td>霊脈、エネルギー鉱脈、霊気結晶、本源エネルギー碎片など</td><td>修練に必要なエネルギー入力を提供</td></tr><tr><td>薬物系資源</td><td>霊薬、仙草、錬丹材料、完成品丹薬など</td><td>修練補助、傷病治療、瓶頸突破</td></tr><tr><td>器材系資源</td><td>修練法器、法則儀器、倍増装置、空間設備など</td><td>修練効率向上、法則操作補助</td></tr><tr><td>空間系資源</td><td>修練秘境、霊気濃度区、法則感悟室、隔離空間など</td><td>特殊な修練環境を提供</td></tr><tr><td>知識系資源</td><td>修練功法、修練心得、法則研究資料、技術文書など</td><td>修練の理論と方法の指導を提供</td></tr><tr><td>生物系資源</td><td>霊獣、霊植、契約生命、共生体など</td><td>修練補助、共生循環、特殊能力</td></tr><tr><td>位面系資源</td><td>未開発位面、位面通道使用権、位面核心碎片など</td><td>大規模な修練と発展空間を提供</td></tr></tbody></table><h3 id="_2-2-資源等級付け" tabindex="-1">2.2 資源等級付け <a class="header-anchor" href="#_2-2-資源等級付け" aria-label="Permalink to &quot;2.2 資源等級付け&quot;">​</a></h3><p>すべての修練資源は希少度と価値に応じて五つの等級に分けられる：</p><table tabindex="0"><thead><tr><th>等級</th><th>名称</th><th>希少度</th><th>分配方式</th></tr></thead><tbody><tr><td>一級</td><td>普通資源</td><td>広く分布、埋蔵量豊富</td><td>無料開放または低価格配給</td></tr><tr><td>二級</td><td>優良資源</td><td>比較的一般的、埋蔵量適中</td><td>基礎配給＋貢献交換</td></tr><tr><td>三級</td><td>稀有資源</td><td>比較的希少、埋蔵量有限</td><td>貢献交換＋申請審批</td></tr><tr><td>四級</td><td>史詩資源</td><td>非常に希少、埋蔵量極少</td><td>競争的分配＋文明級プロジェクト優先</td></tr><tr><td>五級</td><td>伝説資源</td><td>極度に希少、ほぼ絶滅</td><td>文明最高決策機構の専項分配</td></tr></tbody></table><h2 id="第三節-資源開放の核心原則" tabindex="-1">第三節 資源開放の核心原則 <a class="header-anchor" href="#第三節-資源開放の核心原則" aria-label="Permalink to &quot;第三節 資源開放の核心原則&quot;">​</a></h2><h3 id="_3-1-基本保障原則" tabindex="-1">3.1 基本保障原則 <a class="header-anchor" href="#_3-1-基本保障原則" aria-label="Permalink to &quot;3.1 基本保障原則&quot;">​</a></h3><p>すべての生命は基本的な修練を維持するために必要な一級と二級の資源を得る権利がある。基本保障資源は「誰もが道を持つ保障体系」を通じて無料または低価格で配給され、敷居は設けられず、差別もされない。基本保障の基準は万族共和議会が文明の資源状況と発展段階に応じて定期的に調整し、保障水準が文明の負担能力と一致することを確保する。</p><h3 id="_3-2-多労多得原則" tabindex="-1">3.2 多労多得原則 <a class="header-anchor" href="#_3-2-多労多得原則" aria-label="Permalink to &quot;3.2 多労多得原則&quot;">​</a></h3><p>基本保障の上では、三級以上の資源の分配は個人の共生ネットワークへの貢献値を主な根拠とする。貢献が大きいほど、交換できる資源が多く、等級も高くなる。多労多得原則は修練者が自らの境界を高め、文明により大きな貢献をするよう奨励すると同時に、資源が最も効率的に利用できる個人と集団に流れることを確保する。</p><h3 id="_3-3-独占禁止原則" tabindex="-1">3.3 独占禁止原則 <a class="header-anchor" href="#_3-3-独占禁止原則" aria-label="Permalink to &quot;3.3 独占禁止原則&quot;">​</a></h3><p>いかなる個人、組織、種族も修練資源を独占することは厳禁される。独占禁止の具体的な措置は以下を含む：</p><ul><li>単一の個人または組織が保有する三級以上の資源は文明の総埋蔵量の1%を超えてはならない</li><li>買い占め投機の禁止——資源保有者は資源不足時に悪意的に買い占めて価格を吊り上げてはならない</li><li>排他的占有の禁止——公共資源（公共霊脈、公共秘境など）は私人によって排他的に占有されてはならない</li><li>独占禁止法に違反する行為は錨点法院の厳しい制裁を受け、資源没収、貢献値ゼロ、修練権限制限などを含む</li></ul><h3 id="_3-4-持続可能利用原則" tabindex="-1">3.4 持続可能利用原則 <a class="header-anchor" href="#_3-4-持続可能利用原則" aria-label="Permalink to &quot;3.4 持続可能利用原則&quot;">​</a></h3><p>すべての資源の開発と利用は持続可能原則に従わなければならず、池を干して魚を捕るような略奪的採掘は許されない。具体的な要求は以下を含む：</p><ul><li>資源開発速度は資源の自然再生速度を超えてはならない（再生不可能な資源については代替案を策定する必要がある）</li><li>資源開発は環境影響評価を行わなければならず、生態環境に不可逆的な破壊を与えることを防止する</li><li>絶滅危惧資源については、採掘禁止または制限政策を実施し、資源の再生能力を保護する</li><li>技術的手段（法則エンジニアリング、倍増技術など）を通じて稀有資源の人工栽培と合成を奨励し、自然資源への依存を減らす</li></ul><h3 id="_3-5-開放透明原則" tabindex="-1">3.5 開放透明原則 <a class="header-anchor" href="#_3-5-開放透明原則" aria-label="Permalink to &quot;3.5 開放透明原則&quot;">​</a></h3><p>資源の分配プロセスは公開かつ透明でなければならず、すべての生命の監督を受ける：</p><ul><li>すべての公共資源の埋蔵量、分布、開発状況は定期的に社会に公開される</li><li>資源分配の基準、プロセス、結果は公開され照会可能である</li><li>資源分配申訴メカニズムを設け、分配結果に異議のある個人は再審査を申請できる</li><li>錨点法院傘下の「資源公平委員会」が、専門的に資源分配の公平性と合法性を監督する</li></ul><h2 id="第四節-資源開放の具体的メカニズム" tabindex="-1">第四節 資源開放の具体的メカニズム <a class="header-anchor" href="#第四節-資源開放の具体的メカニズム" aria-label="Permalink to &quot;第四節 資源開放の具体的メカニズム&quot;">​</a></h2><h3 id="_4-1-聯産請負メカニズム" tabindex="-1">4.1 聯産請負メカニズム <a class="header-anchor" href="#_4-1-聯産請負メカニズム" aria-label="Permalink to &quot;4.1 聯産請負メカニズム&quot;">​</a></h3><p>聯産請負は修練資源開放の核心的な制度設計であり、その基本的な運営方式は「多労多得分配原理」文書に詳述されている。資源開放の分野における聯産請負の具体的な応用は以下を含む：</p><ul><li><strong>霊脈請負</strong>: 公共霊脈を修練者グループまたは種族コミュニティに請け負わせ、請負者は霊脈の維持と持続可能な開発を担当し、霊脈の生産の一定割合を得る</li><li><strong>薬田請負</strong>: 公共薬田を栽培能力のある修練者に請け負わせ、請負者は霊薬の栽培と養護を担当し、収穫は割合に応じて分配される</li><li><strong>秘境管理</strong>: 公共修練秘境を専門チームに管理を委託し、管理者は秘境の維持と安全を担当し、使用者は合理的な使用料を支払う</li><li><strong>資源探査</strong>: 修練者が未開発区域の資源探査に参加することを奨励し、探査者は発見した新しい資源に対して優先請負権を享有する</li></ul><h3 id="_4-2-貢献値交換メカニズム" tabindex="-1">4.2 貢献値交換メカニズム <a class="header-anchor" href="#_4-2-貢献値交換メカニズム" aria-label="Permalink to &quot;4.2 貢献値交換メカニズム&quot;">​</a></h3><p>共生文明は統一された「貢献値交換システム」を構築し、修練者は共生ネットワークに貢献することで貢献値を蓄積し、貢献値で各種修練資源を交換できる：</p><ul><li>貢献値の獲得経路は以下を含む：修練精進、知識共有、技術革新、公共サービス、生態修復、文明守護など</li><li>交換システムは「明码标价」を実施し、各資源には明確な貢献値価格があり、価格は資源の希少度と需要度に応じて動的に調整される</li><li>交換システムは「前借り」機能をサポートする——将来性のある修練者は一定額の貢献値を前借りして資源交換に使用でき、将来的に貢献することで返済する</li><li>交換システムは錨点ネットワークとリアルタイムで接続され、貢献値の記録と交換の安全で信頼できることを確保する</li></ul><h3 id="_4-3-公共資源無料開放メカニズム" tabindex="-1">4.3 公共資源無料開放メカニズム <a class="header-anchor" href="#_4-3-公共資源無料開放メカニズム" aria-label="Permalink to &quot;4.3 公共資源無料開放メカニズム&quot;">​</a></h3><p>以下のタイプの資源はすべての生命に無料で開放される：</p><ul><li><strong>知識系資源</strong>: 三百套修練体系の基礎功法、公共修練心得、基礎法則研究資料など</li><li><strong>一級エネルギー資源</strong>: 基礎霊気、普通エネルギー結晶などの広く分布する低級エネルギー資源</li><li><strong>公共修練空間</strong>: 公共修練室、基礎法則感悟室、普通隔離空間など</li><li><strong>基礎医療資源</strong>: 基礎治療術法、普通療傷丹薬、基礎リハビリテーションサービスなど</li><li><strong>基礎教育資源</strong>: 基礎修練コース、入門導師指導、通用修練器材使用など</li></ul><h3 id="_4-4-特殊資源定向分配メカニズム" tabindex="-1">4.4 特殊資源定向分配メカニズム <a class="header-anchor" href="#_4-4-特殊資源定向分配メカニズム" aria-label="Permalink to &quot;4.4 特殊資源定向分配メカニズム&quot;">​</a></h3><p>四級、五級などの稀有資源については、「定向分配」メカニズムを実施する：</p><ul><li>稀有資源は文明級重点プロジェクト（錨点建設、位面開発、技術攻略など）に優先的に分配される</li><li>特殊な必要のある個人（重要な境界突破に特定の資源が必要、特殊な傷病の治療に稀有な薬物が必要など）については、申請審批を通じて定向分配を得ることができる</li><li>稀有資源の分配方案は万族共和議会傘下の「資源分配委員会」が策定し、議会の審批を経て実施される</li><li>定向分配の結果は社会に公開され、監督を受ける</li></ul><h2 id="第五節-資源創造と持続可能発展" tabindex="-1">第五節 資源創造と持続可能発展 <a class="header-anchor" href="#第五節-資源創造と持続可能発展" aria-label="Permalink to &quot;第五節 資源創造と持続可能発展&quot;">​</a></h2><p>修練資源開放は「存量の分配」だけでなく、「増量の創造」でもある。共生文明は資源の人工創造と持続可能な開発を大力に奨励する：</p><h3 id="_5-1-資源人工栽培" tabindex="-1">5.1 資源人工栽培 <a class="header-anchor" href="#_5-1-資源人工栽培" aria-label="Permalink to &quot;5.1 資源人工栽培&quot;">​</a></h3><ul><li><strong>霊薬人工栽培</strong>: 法則エンジニアリング技術を通じて、人工環境で各種霊薬を栽培し、野生霊薬への依存を減らす</li><li><strong>エネルギー人工生産</strong>: 物質エネルギー変換装置、法則共振発生器などの技術を通じて、人工的に霊気とエネルギー結晶を生産する</li><li><strong>霊獣人工繁育</strong>: 霊獣繁育基地を設立し、各種霊獣を人工的に育成し、野生霊獣の個体群を保護する</li><li><strong>秘境人工建造</strong>: 空間法則技術を通じて、人工的に修練秘境を建造し、修練空間の供給を増やす</li></ul><h3 id="_5-2-資源循環利用" tabindex="-1">5.2 資源循環利用 <a class="header-anchor" href="#_5-2-資源循環利用" aria-label="Permalink to &quot;5.2 資源循環利用&quot;">​</a></h3><ul><li><strong>エネルギー回収</strong>: エネルギー回収システムを設立し、修練過程で損耗したエネルギー、戦闘で逸散したエネルギーなどを回収して再利用する</li><li><strong>薬物残渣処理</strong>: 錬丹後の薬渣に対して二次抽出と処理を行い、薬物資源の利用率を高める</li><li><strong>器材回収再造</strong>: 廃棄された修練器材を回収して再造し、材料の浪費を減らす</li><li><strong>空間循環使用</strong>: 使用済みの隔離空間、臨時修練空間などをクリーニングして循環使用する</li></ul><h3 id="_5-3-資源代替技術" tabindex="-1">5.3 資源代替技術 <a class="header-anchor" href="#_5-3-資源代替技術" aria-label="Permalink to &quot;5.3 資源代替技術&quot;">​</a></h3><ul><li>稀有資源の代替品の研究開発を奨励し、技術的手段を通じて「普通材料で稀有材料を代替する」ことを実現する</li><li>再生不可能な伝説級資源については、厳格な保護と使用計画を策定すると同時に、代替技術の研究開発への投入を増やす</li><li>「資源代替技術研究開発基金」を設立し、関連する研究プロジェクトに資金援助を提供する</li></ul><h2 id="第六節-資源開放の監督と救済" tabindex="-1">第六節 資源開放の監督と救済 <a class="header-anchor" href="#第六節-資源開放の監督と救済" aria-label="Permalink to &quot;第六節 資源開放の監督と救済&quot;">​</a></h2><h3 id="_6-1-監督メカニズム" tabindex="-1">6.1 監督メカニズム <a class="header-anchor" href="#_6-1-監督メカニズム" aria-label="Permalink to &quot;6.1 監督メカニズム&quot;">​</a></h3><ul><li><strong>錨点ネットワークリアルタイム監測</strong>: 錨点ネットワークはすべての公共資源の開発、分配、使用状況をリアルタイムで監測し、異常を発見したら速やかに预警する</li><li><strong>資源公平委員会</strong>: 専門的に資源分配の公平性と合法性を監督し、告発と苦情を受け付ける</li><li><strong>社会監督</strong>: すべての生命が資源開発と分配における不当な行為を監督し告発することを奨励する</li><li><strong>定期監査</strong>: 毎年資源管理機構に対して独立監査を行い、監査結果を社会に公開する</li></ul><h3 id="_6-2-救済メカニズム" tabindex="-1">6.2 救済メカニズム <a class="header-anchor" href="#_6-2-救済メカニズム" aria-label="Permalink to &quot;6.2 救済メカニズム&quot;">​</a></h3><ul><li><strong>分配申訴</strong>: 資源分配結果に異議のある個人は資源公平委員会に再審査を申請できる</li><li><strong>資源紛争仲裁</strong>: 資源紛争は錨点法院が仲裁し、仲裁結果は法的効力を有する</li><li><strong>被権益侵害救済</strong>: 資源独占、資源略奪などの行為によって損害を受けた個人は錨点法院に訴訟を提起し、賠償を要求できる</li><li><strong>緊急救助</strong>: 特殊な状況（災害、戦争など）では、緊急資源調配メカニズムを起動し、被災集団の基本的な資源需要を確保する</li></ul><h2 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to &quot;結語&quot;">​</a></h2><p>修練資源開放機制は錨点共生文明の経済制度の核心である。それは「基本保障＋多労多得＋独占禁止＋持続可能＋開放透明」の五つの原則を通じて、公平、効率的、持続可能な資源分配体系を構築する。資源開放機制の究極の目標は、すべての生命に同じ量の資源を得させることではなく、すべての生命に資源を得る公平な機会を与え、資源を最も価値を創造できる場所に流し、文明の資源総量を持続可能な前提の下で持続的に成長させることである。修練資源がもはや少数者が独占する私的財産ではなく、万族が共有し循環的に増益する公共の富となったとき、「誰もが道を持つ」という理想が真に実現され、万族共進の目標が真に達成される。</p><h2 id="関連文書" tabindex="-1">関連文書 <a class="header-anchor" href="#関連文書" aria-label="Permalink to &quot;関連文書&quot;">​</a></h2><ul><li>06-多劳多得分配原理 (多労多得分配原理)</li><li>08-人人有路保障体系 (誰もが道を持つ保障体系)</li><li>22-资源分配联产承包机制 (資源分配聯産請負メカニズム)</li></ul>',57)])])}const _=a(d,[["render",e]]);export{c as __pageData,_ as default};
